\begin{equation}
\text{C}\textsubscript{6}\text{H}\textsubscript{12}\text{O}\textsubscript{6} + 6\text{O}\textsubscript{2} \longrightarrow 6\text{CO}\textsubscript{2} + 6\text{H}\textsubscript{2}\text{O}
\end{equation}

\textbf{এক্সেত্রে খ্যান হার (R.Q.) নির্ণয়ের জন্য নিচের সমীকরণ ব্যবহার করা হয়।}

\textbf{খ্যান হার (R.Q.) = $\frac{\text{নির্গত } \text{CO}\textsubscript{2} \text{এর অণুর পরিমাণ}}{\text{গৃহীত } \text{O}\textsubscript{2} \text{এর অণুর পরিমাণ}}$}

\begin{equation}
\text{R.Q.} = \frac{6\text{CO}\textsubscript{2}}{6\text{O}\textsubscript{2}} = \frac{6}{6} = 1
\end{equation}

\textbf{খ্যান প্রক্রিয়ায় শরক্রা, জৈন অ্যাসিড, চর্বি ও প্রোটিন খ্যানিক বস্তু হিসেবে জারিত হয়। খ্যানিক বস্তু এবং খ্যানের ধরনের ওপর খ্যান হার (R.Q.) ভিন্ন ভিন্ন হতে দেখা যায়। যেমন-}

\begin{equation}
\text{গ্লুকোজের (সবাত খ্যান) R.Q.} = \frac{6\text{CO}\textsubscript{2}}{6\text{O}\textsubscript{2}} = \frac{6}{6} = 1
\end{equation}

\begin{equation}
\text{ওলিক অ্যাসিডের R.Q.} = \frac{36\text{CO}\textsubscript{2}}{51\text{O}\textsubscript{2}} = \frac{36}{51} = 0.71
\end{equation}

\begin{equation}
\text{ম্যালিক অ্যাসিডের R.Q.} = \frac{4\text{CO}\textsubscript{2}}{3\text{O}\textsubscript{2}} = \frac{4}{3} = 1.33
\end{equation}

\textbf{প্রোটিনে অক্সিজেনের পরিমাণ কম থাকে, তাই প্রোটিন খ্যানিক বস্তু হিসেবে ব্যবহৃত হলে এদের R.Q. মান 1 এর অনেক কম হয়।}

